INSERT INTO `san_pham` (`ma_san_pham`, `ten_san_pham`, `mo_ta`, `gia_san_pham`, `is_active`, `ma_loai`) VALUES
(1, 'Đắc Nhân Tâm', 'Cuốn sách kinh điển của Dale Carnegie về nghệ thuật giao tiếp và tạo dựng mối quan hệ. Được xuất bản lần đầu năm 1936, đây là một trong những cuốn sách bán chạy nhất mọi thời đại.', 68000.00, 1, 3),
(2, 'Nhà Giả Kim', 'Tiểu thuyết nổi tiếng của Paulo Coelho kể về hành trình của một cậu bé chăn cừu người Tây Ban Nha tên Santiago đi theo giấc mơ của mình.', 79000.00, 1, 1),
(3, 'Sapiens: Lược Sử Loài Người', 'Tác phẩm của Yuval Noah Harari khám phá lịch sử loài người từ thời tiền sử đến thế kỷ 21. Cuốn sách trả lời câu hỏi: Điều gì đã làm cho Homo sapiens trở thành loài thống trị Trái Đất?', 139000.00, 1, 4),
(4, 'Tư Duy Nhanh Và Chậm', 'Daniel Kahneman, người đoạt giải Nobel Kinh tế, giải thích hai hệ thống tư duy: Hệ thống 1 nhanh, bản năng và cảm xúc; Hệ thống 2 chậm hơn, có chủ đích và logic hơn.', 115000.00, 1, 2),
(5, 'Atomic Habits - Thói Quen Nguyên Tử', 'James Clear chia sẻ phương pháp xây dựng thói quen tốt và loại bỏ thói quen xấu. Cuốn sách cung cấp một framework thực tế dựa trên khoa học thần kinh và tâm lý học.', 89000.00, 1, 3),
(6, 'Người Giàu Có Nhất Thành Babylon', 'George S. Clason chia sẻ những nguyên tắc tài chính cổ đại thông qua những câu chuyện ngụ ngôn về cuộc sống ở Babylon cổ đại.', 59000.00, 1, 2),
(7, 'Cây Cam Ngọt Của Tôi', 'Tiểu thuyết của José Mauro de Vasconcelos kể về cậu bé Zezé 5 tuổi với một tuổi thơ đau khổ nhưng đầy ắp trí tưởng tượng. Tác phẩm đã được dịch ra hơn 50 thứ tiếng.', 75000.00, 1, 1),
(8, 'Dám Bị Ghét', 'Tác phẩm của Ichiro Kishimi và Fumitake Koga trình bày triết học của Alfred Adler qua cuộc đối thoại giữa một chàng trai trẻ và một triết gia.', 99000.00, 1, 3),
(9, 'Zero to One', 'Peter Thiel chia sẻ về cách xây dựng các công ty startup tạo ra điều gì đó thực sự mới mẻ, không chỉ cạnh tranh trong thị trường đã có sẵn.', 109000.00, 1, 2),
(10, 'Hoàng Tử Bé', 'Tác phẩm kinh điển của Antoine de Saint-Exupéry. Câu chuyện về một hoàng tử nhỏ từ hành tinh xa xôi đến thăm Trái Đất và những cuộc gặp gỡ đầy ý nghĩa.', 45000.00, 1, 1),
(11, 'Thinking in Systems', 'Donella H. Meadows giới thiệu tư duy hệ thống - một cách tiếp cận mạnh mẽ để hiểu thế giới phức tạp. Cuốn sách giúp bạn nhận ra và phân tích các hệ thống xung quanh.', 125000.00, 1, 4),
(12, 'Doraemon - Tập 1', 'Manga nổi tiếng của Fujiko F. Fujio về chú mèo máy Doraemon từ tương lai đến giúp đỡ cậu bé Nobita. Phù hợp cho mọi lứa tuổi, đặc biệt là thiếu nhi.', 25000.00, 1, 5),
(13, 'Bố Già', 'Tiểu thuyết kinh điển của Mario Puzo về gia đình Corleone, một trong những gia đình mafia quyền lực nhất nước Mỹ. Tác phẩm đã được chuyển thể thành bộ phim bất hủ.', 135000.00, 1, 1),
(14, 'Rèn Luyện Tư Duy Phản Biện', 'Cuốn sách giúp bạn nhận diện và tránh các lỗi suy nghĩ thường gặp, từ đó đưa ra quyết định sáng suốt hơn trong cuộc sống và công việc.', 85000.00, 1, 3),
(15, 'Sản Phẩm Ngừng Kinh Doanh', 'Đây là sản phẩm dùng để kiểm tra tính năng ngừng kinh doanh', 50000.00, 0, 2);

